import{_ as t,o,c as r,ae as a}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"Tool Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/index.md","filePath":"reference/index.md"}'),d={name:"reference/index.md"};function s(c,e,m,n,i,l){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="tool-reference" tabindex="-1">Tool Reference <a class="header-anchor" href="#tool-reference" aria-label="Permalink to &quot;Tool Reference&quot;">​</a></h1><p>Complete index of all tools provided by omm — plugin tools (in-process via OpenClaw) and MCP server tools (out-of-process via stdio JSON-RPC).</p><h2 id="plugin-tools-omm-plugin" tabindex="-1">Plugin Tools (omm-plugin) <a class="header-anchor" href="#plugin-tools-omm-plugin" aria-label="Permalink to &quot;Plugin Tools (omm-plugin)&quot;">​</a></h2><p>These five tools are registered via <code>api.registerTool()</code> and dispatched by the OpenClaw Gateway.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Summary</th></tr></thead><tbody><tr><td><code>omm_state_write</code></td><td>Atomically write a JSON object to a named state key; applies mode-aware validation for ralph/autopilot/team</td></tr><tr><td><code>omm_state_read</code></td><td>Read the current JSON state for a named key; returns the full object including injected timestamps</td></tr><tr><td><code>omm_state_list</code></td><td>List all state keys present in the state directory</td></tr><tr><td><code>omm_ping</code></td><td>Health-check tool; returns <code>{ ok: true }</code> — use to verify the plugin is loaded and responsive</td></tr><tr><td><code>omm_cancel</code></td><td>Cancel an active workflow by setting <code>active=false</code> on the named key&#39;s state</td></tr></tbody></table><p>All plugin tools are registered with <code>{ optional: true }</code> — the host functions normally if omm is not loaded.</p><p>See <a href="/reference/contracts/state-contract.html">State Contract</a> and <a href="/reference/contracts/error-codes.html">Error Codes</a> for input/output details.</p><h2 id="omm-memory-tools" tabindex="-1">omm-memory Tools <a class="header-anchor" href="#omm-memory-tools" aria-label="Permalink to &quot;omm-memory Tools&quot;">​</a></h2><p>The <code>omm-mcp-memory</code> server exposes four tools for persistent cross-session key-value memory.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Summary</th></tr></thead><tbody><tr><td><code>omm_memory_set</code></td><td>Write a value to a named memory key; persists across sessions in <code>{stateRoot}/memory/</code></td></tr><tr><td><code>omm_memory_get</code></td><td>Read the current value for a named memory key; returns <code>null</code> if the key does not exist</td></tr><tr><td><code>omm_memory_list</code></td><td>List all memory keys currently stored</td></tr><tr><td><code>omm_memory_delete</code></td><td>Delete a named memory key and its persisted file</td></tr></tbody></table><h2 id="omm-trace-tools" tabindex="-1">omm-trace Tools <a class="header-anchor" href="#omm-trace-tools" aria-label="Permalink to &quot;omm-trace Tools&quot;">​</a></h2><p>The <code>omm-mcp-trace</code> server exposes four tools for execution trace recording and metrics.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Summary</th></tr></thead><tbody><tr><td><code>omm_trace_record</code></td><td>Append a structured event to the session trace log; optionally include <code>durationMs</code>, <code>toolName</code>, <code>ok</code> for metric aggregation</td></tr><tr><td><code>omm_trace_list</code></td><td>List trace events for a session, optionally filtered by time range or event type</td></tr><tr><td><code>omm_trace_query</code></td><td>Query trace events with structured filters (session, type, since/until timestamps)</td></tr><tr><td><code>omm_trace_metrics</code></td><td>Aggregate P50/P99 latency and error rate from metric-carrying trace records; supports <code>sessionId</code> and <code>sinceMs</code> filters</td></tr></tbody></table><p>See <a href="/reference/contracts/observability.html">Observability Contract</a> for the <code>omm_trace_metrics</code> output schema and aggregation algorithm.</p>',14)])])}const u=t(d,[["render",s]]);export{h as __pageData,u as default};
